"""Build the Korean reading guide from authored, source-labelled summaries."""
from pathlib import Path
from html import escape
import json

ROOT=Path(__file__).resolve().parents[1]
data=json.loads((ROOT/'assets/course-study-data.json').read_text(encoding='utf-8'))
e=lambda v:escape(str(v),quote=True)
ul=lambda items:'<ul>'+''.join('<li>'+e(i)+'</li>' for i in items)+'</ul>'
nav='''<nav class="site-nav" aria-label="주 메뉴"><a href="./index.html">홈</a><a href="./teaching-foundations.html">수업모형 기초</a><a href="./g-flipped-learning.html">G-Flipped Learning</a><a href="./science-g-flipped.html">과학 수업 적용</a><a href="./teaching-models.html">모형 비교</a><a href="./course-materials.html" aria-current="page">수업 자료실</a><a href="./korean-study.html">한국어 공부방</a></nav>'''
sections=[]
for s in data['sections']:
    cards=[]
    for c in s['cards']:
        flow=f'<p class="cg-flow"><strong>학습 흐름</strong><br>{e(c["flow"])}</p>' if c.get('flow') else ''
        flow_note=f'<p class="note">{e(c["flow_note"])}</p>' if c.get('flow_note') else ''
        proposal='<h4>우리 수업에서 추가로 확인할 증거 · 설계 제안</h4>'+ul(c['proposal']) if c.get('proposal') else ''
        cards.append(f'''<article class="cg-card" data-study-card><h3>{e(c['title'])}</h3>{ul(c['core'])}{flow}{flow_note}<details><summary>평가 증거·설계 질문·출처 보기</summary><h4>배움을 확인할 증거</h4>{ul(c['evidence'])}{proposal}<h4>수업 디자인 질문 · 자료를 바탕으로 만든 질문</h4>{ul(c['questions'])}<p class="callout">{e(c['caution'])}</p><div class="source"><strong>읽을 곳</strong>{ul(c['refs'])}</div></details></article>''')
    sources=''.join(f'''<tr><th scope="row"><code>{e(x['file'])}</code></th><td>{e(x['type'])}</td><td>{e(x['read'])}<br><span class="note">{e(x['location'])}</span></td></tr>''' for x in s['sources'])
    sections.append(f'''<section id="{e(s['id'])}" class="cg-topic" data-study-topic><p class="eyebrow">{e(s['folder'])} · {e(s['planned'])}</p><h2>{e(s['title'])}</h2><p>{e(s['goal'])}</p><div class="cg-cards">{''.join(cards)}</div><details class="cg-sources"><summary>이 주제의 원자료와 확인 범위</summary><div class="table-wrap"><table><thead><tr><th>찾을 파일명</th><th>자료 성격</th><th>실제로 확인한 범위·읽을 위치</th></tr></thead><tbody>{sources}</tbody></table></div></details></section>''')
tabs=''.join(f'<a href="#{s["id"]}">{e(s["title"].split(" · ")[0].split("：")[0])}</a>' for s in data['sections'])
planned=''.join(f'<tr><th scope="row">{x["week"]}주</th><td>{e(x["topic_korean"])}</td></tr>' for x in data['planned_weeks'])
connections=''.join(f'<article class="card"><h3>{e(x["title"])}</h3><p class="note">{e(x["kind"])}</p><p>{e(x["use"])}</p><p class="source"><code>{e(x["file"])}</code></p></article>' for x in data['connections'])
originals=''.join(f'<li><code>{e(name)}</code></li>' for name in data['english_files'])
science_connection='''<section id="science-connections"><h2>함께 해 온 과학 수업 사례로 연결하기</h2><p>대학원 수업 폴더의 175개 목록과 별도로, 공동연구의 최종 보고서·공개수업 지도안·발표자료를 찾아 확인했습니다. 아래는 기존 수업이며, 게임 사전학습·진단 뱃지·파티 레이드는 이번에 추가하는 설계입니다.</p><div class="cg-cards"><article class="card"><h3>식물박람회 · 분류에서 질문과 설명으로</h3><p>초등 6학년 ‘식물의 구조와 기능’에서 공통 식물 자료를 분류하고 모둠의 탐구 질문과 소개 계획을 만듭니다. 지도안은 학생의 이해와 계획판을 보고 질문·자료·역할 지원을 조절합니다.</p><p class="source">「질문하는 학교 수업 지도안(6쪽 축약본)」 1·4–6쪽. 「데이터 기반 레벨업 프로젝트로 미래과학역량 기르기」 최종 보고서 10–14·27–28쪽.</p></article><article class="card"><h3>속력과 안전 · 측정에서 설계 근거로</h3><p>초등 6학년 ‘물체의 운동’에서 모형 자동차의 실험 조건을 정하고 반복 측정하여 안전장치 조건을 설명합니다. 측정·해석·수정의 증거와 개인 설명을 확인합니다.</p><p class="source">같은 최종 보고서 20–24·30–32쪽. 「(윤태영)수업 ppt」의 목표와 실험 흐름 대조.</p></article></div><p>최종 보고서는 실행 장면과 교사 성찰을 기록합니다. 점수 표의 집계 기준은 추가 확인이 필요해 이 정리에 개선 수치를 넣지 않았습니다. 새 모형의 효과를 이미 확인한 결과로 제시하지 않습니다.</p><a class="study-start" href="./science-g-flipped.html">기존 사례와 새 적용안, 발표 구성 함께 보기 →</a></section>'''

page=f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="교수자 강의와 수강생 발표, 워크시트를 바탕으로 수업모형의 기초부터 게임·인공지능 협업까지 읽는 한국어 수업 자료실"><title>수업 자료실 · 호모 루덴스</title><link rel="stylesheet" href="./assets/lab.css"><link rel="stylesheet" href="./assets/course-materials.css"></head><body><a class="skip-link" href="#main">본문으로 건너뛰기</a><div class="shell"><header class="masthead"><a class="brand" href="./index.html"><span class="brand-mark" aria-hidden="true">✦</span>호모 루덴스</a>{nav}</header><main id="main"><header class="page-hero"><p class="eyebrow">강의자료에서 우리 수업 디자인으로 · 2026년 11월 24일 정리</p><h1>앞 수업부터 다시 연결하는<br>수업 자료실</h1><p class="lede">기초를 이해하고, 모형의 차이를 읽고, 우리 수업에 옮깁니다. 교수자 자료·발표·학습 노트·자체 설계안을 구분한 <strong>8개 주제, 29개 한국어 학습카드</strong>입니다.</p><div class="lesson-links"><a href="./teaching-foundations.html">먼저: 수업모형의 기초</a><a href="./g-flipped-learning.html">우리의 게임 통합 모형</a><a href="./teaching-models.html">다섯 학습 구조 비교</a></div></header>
<div class="page-body cg-body"><section id="scope"><h2>어디까지 찾고 확인했나</h2><div class="cg-stats"><div><strong>175</strong><span>대상 형식의 파일 목록</span></div><div><strong>72</strong><span>주차 폴더 중심 우선 목록</span></div><div><strong>57</strong><span>추가 하위 폴더 자료</span></div><div><strong>46</strong><span>보관 폴더·첨부 자료</span></div></div><p>‘혁신적 수업방법 이상수’ 수업 폴더를 하위 폴더까지 검색했습니다. 문서·발표·한글 문서·학습 노트·웹 문서 형식이 대상이며, 같은 자료의 여러 형식과 복사본도 파일 수에 포함합니다. <strong>175편을 모두 정독했다는 뜻은 아닙니다.</strong> 실제 읽은 범위는 아래 원자료 표에 따로 표시했습니다.</p><p>정리의 중심은 교수자 강의 30쪽, 교수계획서, 초반 분석 워크시트, 문제·경험·만들기·게임·인공지능 수업 자료입니다. 쪽수는 문서 첫 장부터 센 순서, 발표자료는 실제 슬라이드 순서입니다.</p><div class="callout"><strong>자료의 지위를 구분합니다.</strong><p>교수자 강의는 이 수업에서 배운 개념과 분석틀의 근거입니다. 학생 발표는 해당 팀의 문헌 해석과 사례 분석입니다. 아래 학습 질문과 새 평가 예시는 이를 바탕으로 만든 제안입니다. 원문 논문의 효과를 이번에 모두 재검증한 것은 아닙니다.</p></div><p class="note">원본 파일은 개인 수업 폴더에서 찾을 수 있도록 정확한 파일명을 남겼습니다. 이 사이트에는 한국어 요약과 읽을 위치를 싣습니다. 영문 파일명은 원자료를 찾기 위한 표기입니다.</p></section>
<section id="route"><h2>이 순서로 공부하면 됩니다</h2><ol class="cg-route"><li><strong>기초:</strong> 교수자 자료 3–7쪽으로 모형의 의미와 다섯 요소를 읽습니다.</li><li><strong>분석:</strong> 워크시트의 전제·구조·기제·정합으로 기존 모형 하나를 뜯어봅니다.</li><li><strong>비교:</strong> 같은 문제를 추론·제작·실천·토론 중 어떤 구조로 배울지 비교합니다.</li><li><strong>결합:</strong> 몰입·성장·인공지능 협업을 학습 활동과 평가에 연결합니다.</li><li><strong>설계:</strong> 사전 게임학습의 진단 자료로 파티·개인 미션·팀 미션을 바꾸고, 실제 수업에서 확인할 증거를 정합니다.</li></ol><nav class="lesson-links" aria-label="자료 주제 바로가기">{tabs}</nav><div id="course-filter" hidden><label for="course-search">공부할 내용 찾기</label><input id="course-search" type="search" placeholder="예: 평가, 생산적 실패, 인공지능, 질문"><p id="course-search-status" role="status">29개 학습카드를 표시합니다.</p></div></section>
{''.join(sections)}
<section id="earlier-work"><h2>기존 공부와 설계 작업도 이어 읽기</h2><div class="cg-cards">{connections}</div><p>논문을 한국어로 공부하려면 <a href="./korean-study.html">한국어 공부방</a>, 독서·이야기섬과 공동 탐구의 이전 설계는 <a href="./co-learning-model.html#lineage">기존 작업의 연결</a>에서 이어집니다.</p></section>
{science_connection}<section id="gaps"><h2>비어 있거나 아직 확인을 남긴 자료</h2><ul><li><strong>1주차 참여적 수업 설계:</strong> 11월 12일 강의 정리에 별도 메모·자료가 남아 있지 않다고 적혀 있습니다. 이번 검색에서도 별도 본문을 확보하지 못했습니다.</li><li><strong>3주차 종합정리 웹 문서:</strong> 파일은 있지만 크기가 0바이트입니다. 위 국제 동향 학습카드는 실제로 확인한 네 한국어 발표를 바탕으로 새로 정리했습니다.</li><li><strong>확장현실·하이플렉스:</strong> 교수계획서의 예정 12주차 주제와 참고문헌은 확인했습니다. 해당 강의 본문을 읽은 것처럼 정리하지 않았습니다.</li><li><strong>영문 원문 30개:</strong> 첫 두 쪽의 서지·도입부 텍스트를 확보했습니다. 전체 본문 검토와 연구의 질 평가는 남아 있습니다.</li><li><strong>보관·심화 폴더:</strong> 전체 목록을 만들고 관련 기존 설계를 골라 읽었습니다. 모든 첨부자료의 본문을 검토한 것은 아닙니다.</li></ul><details><summary>영문 원문 보관 목록 30개 · 학습 설명은 위 한국어 카드 이용</summary><ul class="cg-file-list">{originals}</ul></details></section>
<section id="syllabus"><h2>폴더 주차와 교수계획서 주차가 다릅니다</h2><p>예를 들어 ‘3주’ 폴더의 국제 동향은 계획서에서 예정 4주차입니다. 위에는 두 표기를 함께 적었습니다. 다음 표는 <strong>교수계획서의 예정 순서</strong>이며 실제 진행 일정을 단정하지 않습니다.</p><details><summary>교수계획서의 예정 15주 전체 보기</summary><div class="table-wrap"><table><thead><tr><th>예정 주차</th><th>주제</th></tr></thead><tbody>{planned}</tbody></table></div></details><p class="source">출처: 교수계획서.hwp, 6. 주별 수업계획. 폴더명과 실제 읽은 자료의 표지·본문을 함께 확인했습니다.</p></section>
<section class="callout"><h2>이제 우리의 모형에 적용하기</h2><p>수업 전 게임학습으로 현재 수행과 지원 필요를 알아보고, 그 증거로 파티와 미션을 설계합니다. 수업 중 레이드에서 함께 해결하고, 개인의 배움을 다시 확인해 다음 도전을 바꿉니다.</p><a class="study-start" href="./g-flipped-learning.html">게임 통합 수업모형 설계안 보기 →</a></section></div></main><footer class="site-footer"><p>호모 루덴스 · 재미있고 즐겁게 가르치고 배우는 교사를 위하여</p><p>자료 정리와 자체 설계 제안 · 원자료의 효과 검증과 구분</p></footer></div><script src="./assets/course-materials.js"></script></body></html>'''
(ROOT/'course-materials.html').write_text(page,encoding='utf-8')
print('Built course materials: 8 topics, 29 cards, source-level reading scope.')
